<template>
  <main class="builder-page">
    <section class="builder-shell">
      <div class="builder-heading">
        <div><p class="kicker">UMS INTERNAL TOOL</p><h1>Email Campaign Builder</h1><p>Featured machines are selected automatically. Reorder them, add a campaign price or POR, then copy the finished HTML into Brevo.</p></div>
        <div class="count">{{ selectedMachines.length }} selected</div>
      </div>
      <section class="controls">
        <label>Campaign headline<input v-model="headline" type="text" /></label>
        <label>Intro text<textarea v-model="intro" rows="3" /></label>
        <div class="actions"><button type="button" @click="resetFeatured">Reload Featured</button><button type="button" class="primary" @click="copyHtml">{{ copyLabel }}</button></div>
      </section>
      <section class="workspace">
        <div class="machine-picker">
          <h2>Campaign Machines</h2><p class="help">Drag to reorder. Enter a price such as $49,500 or leave POR.</p>
          <div v-for="(machine,index) in selectedMachines" :key="machine.InvID" class="selected-row" draggable="true" @dragstart="dragIndex=index" @dragover.prevent @drop="dropAt(index)">
            <div class="selected-top"><span class="drag">☰</span><div class="row-copy"><strong>{{ machineTitle(machine) }}</strong><small>Stock #{{ machine.InvID }}</small></div><button type="button" class="remove" @click="removeMachine(machine.InvID)">Remove</button></div>
            <label class="price-label">Email price<input v-model="priceText[machine.InvID]" type="text" placeholder="POR or $49,500" /></label>
          </div>
          <details><summary>Add another active machine</summary><input v-model="search" class="search" type="search" placeholder="Search stock #, manufacturer or model" /><button v-for="machine in availableMachines" :key="machine.InvID" type="button" class="add-row" @click="addMachine(machine)">+ {{ machineTitle(machine) }} — #{{ machine.InvID }}</button></details>
        </div>
        <div class="preview-wrap">
          <div class="preview-label">EMAIL PREVIEW</div>
          <div class="email-preview">
            <div class="email-header"><img src="/Images/ums-logo.png" alt="Used Machinery Source" class="email-logo" /><div class="contact-links"><a href="tel:+12569801200">(256) 980-1200</a><span>•</span><a href="mailto:jon@usedms.com">jon@usedms.com</a><span>•</span><a href="https://usedmachinerysource.com" target="_blank">usedmachinerysource.com</a></div></div>
            <div class="email-intro"><h2>{{ headline }}</h2><p>{{ intro }}</p></div>
            <div class="machine-grid"><article v-for="machine in selectedMachines" :key="machine.InvID" class="email-machine"><img v-if="machineImages[machine.InvID]" :src="imageUrl(machine.InvID)" :alt="machineTitle(machine)" /><div class="email-machine-copy"><h3>{{ machineTitle(machine) }}</h3><p class="type">{{ webDescription(machine) }}</p><p class="stock"><strong>Stock #{{ machine.InvID }}</strong></p><p class="price">{{ priceText[machine.InvID] || 'POR' }}</p><p class="spec">{{ advertisingSpec(machine) }}</p><a :href="machineUrl(machine)" target="_blank">LEARN MORE</a></div></article></div>
            <div class="email-footer"><strong>Used Machinery Source, LLC</strong><br />Florence, Alabama<br /><a href="https://usedmachinerysource.com/equipment">View Current Inventory</a></div>
          </div>
        </div>
      </section>
    </section>
  </main>
</template>
<script setup>
import machinesData from '~/assets/data/machines.json'
useHead({title:'UMS Email Campaign Builder',meta:[{name:'robots',content:'noindex,nofollow'}]})
const headline=ref('Featured Machinery Available Now')
const intro=ref('Take a look at these machines currently available through Used Machinery Source. Contact us for additional information, pricing, or to arrange an inspection.')
const selectedMachines=ref([]),machineImages=ref({}),priceText=ref({}),dragIndex=ref(null),search=ref(''),copyLabel=ref('Copy HTML for Brevo')
const offMarketValue=m=>m.OffMarket??m.Off_Market??0
const webDescription=m=>m.WebDesc||m.Web_Desc||''
const advertisingSpec=m=>m.AdvSpec||m.Adv_Spec||''
const machineTitle=m=>[m.Year,m.Manufacturer,m.Model].filter(Boolean).join(' ')
const slug=m=>`${m.Manufacturer||''}-${m.Model||''}`.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')
const machineUrl=m=>`https://usedmachinerysource.com/equipment/${m.InvID}/${slug(m)}`
const imageUrl=id=>`https://usedmachinerysource.com/Images/${machineImages.value[id]}`
const activeMachines=computed(()=>machinesData.filter(m=>Number(m.Sold)===0&&Number(offMarketValue(m))===0&&Number(m.dont_advertise)===0))
const availableMachines=computed(()=>{const chosen=new Set(selectedMachines.value.map(m=>String(m.InvID))),q=search.value.trim().toLowerCase();return activeMachines.value.filter(m=>!chosen.has(String(m.InvID))).filter(m=>!q||`${m.InvID} ${m.Manufacturer} ${m.Model} ${webDescription(m)}`.toLowerCase().includes(q)).slice(0,20)})
function ensurePrice(m){if(!(m.InvID in priceText.value))priceText.value[m.InvID]='POR'}
async function loadImage(m){if(machineImages.value[m.InvID])return;try{const files=await $fetch('/api/images',{query:{invID:m.InvID}});if(files?.length)machineImages.value[m.InvID]=files[0]}catch(e){console.error(`Could not load image for ${m.InvID}`,e)}}
async function resetFeatured(){selectedMachines.value=activeMachines.value.filter(m=>Number(m.Featured)===1);for(const m of selectedMachines.value){ensurePrice(m);await loadImage(m)}}
async function addMachine(m){selectedMachines.value.push(m);ensurePrice(m);search.value='';await loadImage(m)}
function removeMachine(id){selectedMachines.value=selectedMachines.value.filter(m=>String(m.InvID)!==String(id))}
function dropAt(index){if(dragIndex.value===null||dragIndex.value===index)return;const next=[...selectedMachines.value],[moved]=next.splice(dragIndex.value,1);next.splice(index,0,moved);selectedMachines.value=next;dragIndex.value=null}
function esc(v=''){return String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function machineCell(m){const img=machineImages.value[m.InvID]?`<img src="${imageUrl(m.InvID)}" alt="${esc(machineTitle(m))}" width="180" style="display:block;width:180px;max-width:100%;height:auto;border:0;margin:0 auto 14px;">`:'';const price=esc(priceText.value[m.InvID]||'POR');return `<td width="50%" valign="top" style="width:50%;padding:8px;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background:#f4f7fb;border:2px solid #9fb4d3;"><tr><td style="padding:16px;text-align:center;font-family:Arial,sans-serif;">${img}<h2 style="margin:0 0 6px;font-size:19px;line-height:1.2;color:#1c4587;">${esc(machineTitle(m))}</h2><p style="margin:0 0 7px;font-size:13px;line-height:1.35;color:#434343;">${esc(webDescription(m))}</p><p style="margin:0 0 7px;font-size:13px;color:#222;"><strong>Stock #${esc(m.InvID)}</strong></p><p style="margin:0 0 10px;font-size:18px;font-weight:bold;color:#1c4587;">${price}</p><p style="margin:0 0 14px;font-size:13px;line-height:1.4;color:#333;">${esc(advertisingSpec(m))}</p><a href="${machineUrl(m)}" style="display:inline-block;background:#1c4587;color:#fff;text-decoration:none;font-weight:bold;font-size:12px;padding:10px 14px;">LEARN MORE</a></td></tr></table></td>`}
function buildEmailHtml(){let rows='';for(let i=0;i<selectedMachines.value.length;i+=2){const left=machineCell(selectedMachines.value[i]),right=selectedMachines.value[i+1]?machineCell(selectedMachines.value[i+1]):'<td width="50%" style="width:50%;padding:8px;"></td>';rows+=`<tr>${left}${right}</tr>`}return `<!doctype html><html><body style="margin:0;padding:0;background:#eceff3;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background:#eceff3;"><tr><td align="center" style="padding:24px 10px;"><table role="presentation" width="600" cellspacing="0" cellpadding="0" border="0" style="width:100%;max-width:600px;background:#f5f5f5;"><tr><td style="background:#fff;padding:0 20px 2px;text-align:center;font-family:Arial,sans-serif;border-bottom:1px solid #d9dee7;"><img src="https://usedmachinerysource.com/Images/ums-logo.png" alt="Used Machinery Source" width="300" style="display:block;width:300px;max-width:90%;height:auto;border:0;margin:0 auto -14px;"><div style="font-size:12px;line-height:1.15;color:#434343;margin-top:-6px;"><a href="tel:+12569801200" style="color:#1c4587;text-decoration:none;font-weight:bold;">(256) 980-1200</a>&nbsp;&nbsp;•&nbsp;&nbsp;<a href="mailto:jon@usedms.com" style="color:#1c4587;text-decoration:none;font-weight:bold;">jon@usedms.com</a>&nbsp;&nbsp;•&nbsp;&nbsp;<a href="https://usedmachinerysource.com" style="color:#1c4587;text-decoration:none;font-weight:bold;">usedmachinerysource.com</a></div></td></tr><tr><td style="padding:20px 24px 14px;text-align:center;font-family:Arial,sans-serif;background:#f5f5f5;"><h1 style="margin:0 0 8px;font-size:28px;color:#222;">${esc(headline.value)}</h1><p style="margin:0;font-size:16px;line-height:1.45;color:#555;">${esc(intro.value)}</p></td></tr><tr><td style="padding:0 12px 22px;background:#f5f5f5;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0">${rows}</table></td></tr><tr><td style="padding:22px;text-align:center;background:#e9e9e9;font-family:Arial,sans-serif;font-size:13px;line-height:1.6;color:#555;"><strong>Used Machinery Source, LLC</strong><br>Florence, Alabama<br><a href="https://usedmachinerysource.com/equipment" style="color:#1c4587;">View Current Inventory</a></td></tr></table></td></tr></table></body></html>`}
async function copyHtml(){try{await navigator.clipboard.writeText(buildEmailHtml());copyLabel.value='Copied!';setTimeout(()=>{copyLabel.value='Copy HTML for Brevo'},2200)}catch{copyLabel.value='Copy failed'}}
onMounted(resetFeatured)
</script>
<style scoped>
