lor:#aaa;color:#555}details{margin-top:18px}summary{cursor:pointer;font-weight:700;color:#1c4587}.add-row{display:block;width:100%;text-align:left;margin-top:6px;border-color:#d7dde5;color:#333;font-weight:400}.preview-wrap{padding:18px}.preview-label{font-size:11px;letter-spacing:1.4px;font-weight:700;color:#777;margin:0 0 10px}.email-preview{max-width:600px;margin:auto;border:1px solid #ddd;background:#f5f5f5}.email-header{background:#fff;text-align:center;padding:0 20px 2px;border-bottom:1px solid #d9dee7}.email-logo{display:block;width:300px;max-width:90%;height:auto;margin:0 auto -14px}.contact-links{display:flex;justify-content:center;align-items:center;gap:7px;flex-wrap:wrap;font-size:12px;line-height:1.15;margin-top:-6px}.contact-links a{color:#1c4587;text-decoration:none;font-weight:700}.contact-links span{color:#999}.email-intro{text-align:center;padding:20px 24px 14px}.email-intro h2{font-size:28px;margin:0 0 8px}.email-intro p{color:#555;line-height:1.45;margin:0}.machine-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;padding:0 14px 24px}.email-machine{background:#f4f7fb;border:2px solid #9fb4d3;border-radius:6px;overflow:hidden;text-align:center}.email-machine img{display:block;width:180px;max-width:100%;height:135px;object-fit:contain;background:#fff;margin:14px auto 0}.email-machine-copy{padding:14px 16px 18px}.email-machine h3{color:#1c4587;font-size:19px;line-height:1.2;margin:0 0 6px}.email-machine p{line-height:1.4}.email-machine .type{margin:0 0 7px;color:#434343;font-size:13px}.email-machine .stock{margin:0 0 7px;font-size:13px}.email-machine .price{margin:0 0 10px;color:#1c4587;font-size:18px;font-weight:700}.email-machine .spec{margin:0 0 14px;font-size:13px}.email-machine a{display:inline-block;background:#1c4587;color:#fff;text-decoration:none;font-weight:700;font-size:12px;padding:10px 14px;border-radius:4px}.email-footer{text-align:center;background:#e9e9e9;padding:22px;color:#555;font-size:13px;line-height:1.6}.email-footer a{color:#1c4587}@media(max-width:900px){.controls,.workspace{grid-template-columns:1fr}.machine-picker{position:static}.builder-heading{align-items:flex-start;flex-direction:column}.actions{flex-wrap:wrap}}@media(max-width:620px){.machine-grid{grid-template-columns:1fr}}
</style>